styles:
.rte-pair { display: grid; grid-template-columns: 1fr 1fr; gap: 1rem; }
    @media (max-width: 800px) { .rte-pair { grid-template-columns: 1fr; } }
    pre.output {
      font-family: ui-monospace, monospace; font-size: .78rem;
      background: var(--is-bg-elev); border: 1px solid var(--is-border);
      border-radius: var(--is-radius); padding: .65rem .85rem;
      max-height: 12rem; overflow: auto;
      white-space: pre-wrap;
    }

blocks.code:
const r = document.querySelector('is-rte');
r.value;        // HTML actual
r.text;         // texto plano
r.focus();
r.exec('bold'); // bold, italic, underline, strike
r.format('h2'); // h1..h6, p, blockquote, pre
r.link();       // prompt → crea <a>
r.clear();      // sin formato, sin listas
r.undo(); r.redo();

r.addEventListener('is-input',  e => /* cada keystroke */);
r.addEventListener('is-change', e => console.log(e.detail.value));
r.addEventListener('is-blur',   () => /* perdió foco */);

